  scene: { svg: `<svg viewBox="0 0 1200 640" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="640" fill="#fbe9e7"/><rect y="500" width="1200" height="140" fill="#bcaaa4"/><g transform="translate(300 300)"><rect x="-200" y="-140" width="400" height="340" fill="#fff8e1" stroke="#8d6e63" stroke-width="8"/><path d="M-220 -140L0 -260L220 -140Z" fill="#a1887f"/><path d="M0 -260V-320" stroke="#5d4037" stroke-width="6"/><g><animateTransform attributeName="transform" type="rotate" values="-20 0 -300;20 0 -300;-20 0 -300" dur="2s" repeatCount="indefinite"/><path d="M-16 -300h32l8 30h-48z" fill="#ffb300"/></g><rect x="-150" y="-80" width="300" height="120" fill="#2e7d32" stroke="#6d4c41" stroke-width="6"/><path d="M-120 -40h80M-120 -10h120" stroke="#ffffff" stroke-width="4"><animate attributeName="stroke-dasharray" values="0 200;200 0" dur="3s" repeatCount="indefinite"/></path><g fill="#ffcc80"><circle cx="-110" cy="110" r="22"/><circle cx="-30" cy="110" r="22"/><circle cx="50" cy="110" r="22"/><circle cx="130" cy="110" r="22"/></g><g fill="#5c6bc0"><path d="M-130 132h40l6 60h-52zM-50 132h40l6 60h-52zM30 132h40l6 60h-52zM110 132h40l6 60h-52z"/></g></g><g transform="translate(880 280)"><path d="M-80 -40q80-120 160 0v200h-160z" fill="#f8bbd0" stroke="#ad1457" stroke-width="5"/><circle cy="-90" r="50" fill="#ffe0b2"/><path d="M-50 -120q50-60 100 0q-20-30-50-30t-50 30z" fill="#fff59d"/><path d="M-30 -150l10-30l20 20l20-20l10 30z" fill="#ffd54f" stroke="#f9a825" stroke-width="3"/><path d="M-120 200h240" stroke="#8d6e63" stroke-width="12"/><rect x="100" y="-20" width="110" height="140" rx="6" fill="#fffde7" stroke="#8d6e63" stroke-width="4"><animate attributeName="y" values="-20;-30;-20" dur="3s" repeatCount="indefinite"/></rect><path d="M120 10h70M120 40h70M120 70h50" stroke="#8d6e63" stroke-width="4"/></g></svg>`,
   points: [{ t: 'Škola', d: 'Ratio educationis z roku 1777 zaviedla povinnú školu pre deti od 6 do 12 rokov.', e: 'Deti začali chodiť do školy.', ic: 'book', x: 25, y: 40 }, { t: 'Žiaci', d: 'V dedinských školách sa učilo čítanie, písanie, počty a náboženstvo.', e: 'Žiaci sa učili čítať a písať.', ic: 'people', x: 25, y: 75 }, { t: 'Mária Terézia', d: 'Panovníčka vládla v rokoch 1740 až 1780.', e: 'Mária Terézia vládla 40 rokov.', ic: 'crown', x: 73, y: 22 }, { t: 'Listina', d: 'Reformy vychádzali ako nariadenia, napríklad urbár o povinnostiach poddaných.', e: 'Panovníčka vydávala zákony.', ic: 'map', x: 88, y: 48 }, { t: 'Zvon', d: 'Pri dedinských kostoloch často fungovali aj školy.', e: 'Školy boli často pri kostoloch.', ic: 'cross', x: 25, y: 4, l: 2 }] },
  cards: [{ q: 'Kedy vládla Mária Terézia?', a: 'V rokoch 1740 až 1780.' }, { q: 'Čo zaviedla Ratio educationis?', a: 'Právne zaviedla povinnú školskú dochádzku pre deti od 6 do 12 rokov v Uhorsku. V praxi sa zavádzala postupne.' }, { q: 'Čo upravila urbárska reforma?', a: 'Povinnosti poddaných voči zemepánom.' }, { q: 'Kto zrušil nevoľníctvo?', a: 'Jozef II., v roku 1785.' }, { q: 'Proti ktorej chorobe podporovala očkovanie?', a: 'Proti kiahňam.', l: 2 }, { q: 'Čo bol toleranční patent?', a: 'Nariadenie Jozefa II., ktoré povolilo nekatolíkom slobodnejšie vyznávať vieru.', l: 2 }],
