  scene: { svg: `<svg viewBox="0 0 1200 640" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="640" fill="#f3f4f8"/><rect y="560" width="1200" height="80" fill="#cfd8dc"/><g transform="translate(600 300)"><path d="M0 -200V250" stroke="#8d6e63" stroke-width="14"/><path d="M-120 250h240" stroke="#8d6e63" stroke-width="18"/><circle cy="-210" r="18" fill="#ffb300"/><g><animateTransform attributeName="transform" type="rotate" values="-4 0 -190;4 0 -190;-4 0 -190" dur="5s" repeatCount="indefinite"/><path d="M-380 -190H380" stroke="#8d6e63" stroke-width="10"/><g stroke="#8d6e63" stroke-width="3"><path d="M-380 -190l-60 120M-380 -190l60 120M0 -190l0 0M380 -190l-60 120M380 -190l60 120"/></g><path d="M-450 -70h140q-70 40-140 0z" fill="#90caf9"/><path d="M310 -70h140q-70 40-140 0z" fill="#ef9a9a"/><g transform="translate(-380 -100)"><rect x="-40" y="-10" width="80" height="40" fill="#1565c0"/><path d="M-30 -10v-20h60v20" fill="none" stroke="#1565c0" stroke-width="6"/></g><g transform="translate(380 -110)"><path d="M-30 30h60l-6-40h-48z" fill="#c62828"/><path d="M-20 -10v-20M0 -10v-26M20 -10v-20" stroke="#c62828" stroke-width="6"/></g></g><g transform="translate(0 60)"><rect x="-70" y="-60" width="140" height="120" fill="#fff8e1" stroke="#6d4c41" stroke-width="6"/><path d="M-50 -30h100M-50 0h100M-50 30h70" stroke="#6d4c41" stroke-width="5"/></g></g><g transform="translate(600 120)"><path d="M-40 0l40-40l40 40z" fill="#43a047"><animate attributeName="opacity" values="0.6;1;0.6" dur="3s" repeatCount="indefinite"/></path></g></svg>`,
   points: [{ t: 'Zákonodarná moc', d: 'Národná rada SR prijíma zákony. Na obrázku je to ľavá miska.', e: 'Parlament prijíma zákony.', ic: 'book', x: 18, y: 25 }, { t: 'Výkonná moc', d: 'Vláda vykonáva zákony a riadi štát, prezident je hlava štátu s právomocami podľa ústavy. Pravá miska.', e: 'Vláda riadi štát podľa zákonov.', ic: 'crown', x: 82, y: 25 }, { t: 'Súdna moc', d: 'Súdy sú stredom váh: rozhodujú spory nezávisle od ostatných.', e: 'Súdy rozhodujú spravodlivo.', ic: 'cross', x: 50, y: 30 }, { t: 'Ústava', d: 'Najvyšší zákon, na ktorom stojí celý štát.', e: 'Ústava je najvyšší zákon.', ic: 'map', x: 50, y: 58 }, { t: 'Rovnováha', d: 'Zložky moci sa navzájom kontrolujú, aby žiadna nebola príliš silná.', e: 'Moci sa navzájom strážia.', ic: 'bolt', x: 50, y: 12, l: 2 }] },
