  quiz: [{ q: 'Kto prijíma zákony?', o: ['Národná rada SR', 'Prezident', 'Súdy'], k: 0, w: 'Zákonodarnú moc má parlament.' }, { q: 'Ku ktorej moci patrí vláda?', o: ['K výkonnej', 'K súdnej', 'K zákonodarnej'], k: 0, w: 'Vláda je vrcholný orgán výkonnej moci.' }, { q: 'Čo je najvyšší zákon Slovenska?', o: ['Ústava SR', 'Školský poriadok', 'Občiansky preukaz'], k: 0, w: 'Ústava stojí nad všetkými ostatnými zákonmi.' }, { q: 'Prečo musia byť súdy nezávislé?', o: ['Aby rozhodovali spravodlivo bez tlaku', 'Aby mohli písať zákony', 'Aby riadili vládu'], k: 0, w: 'Sudcovi nesmie nikto prikazovať, ako rozhodnúť.', l: 2 }],
